# 작업 길이가 일정 주기로 두 배가 된다면, t개월 뒤 몇 배인가
def growth(months, doubling_months):
    return 2 ** (months / doubling_months)

start_min = 60  # 지금 AI 가 50% 확률로 해내는 작업: 사람 기준 1시간이라고 가정
for label, d in [("일반 과제(7개월)", 7.0), ("코딩(70일=2.3개월)", 70 / 30.4)]:
    for m in (12, 24):
        g = growth(m, d)
        print(f"{label:16s} {m:2d}개월 뒤 x{g:7.1f} → 약 {start_min * g / 60:7.1f}시간짜리 작업")

# 제안 비교 — 강의의 우선순위(팀 > 일 > 배울 속도 > 연봉·브랜드)를 가중치로
W = {"팀": 0.35, "일의 내용": 0.25, "배울 속도": 0.20, "연봉": 0.10, "브랜드": 0.10}
offers = {
    "A 유명 브랜드, 팀은 서명 뒤": {"팀": 1, "일의 내용": 2, "배울 속도": 3, "연봉": 5, "브랜드": 5},
    "B 덜 알려진 회사, 팀 확정":   {"팀": 5, "일의 내용": 4, "배울 속도": 4, "연봉": 3, "브랜드": 2},
}
for name, s in offers.items():
    print(f"{name}: {sum(W[k] * s[k] for k in W):.2f}")
# 가중치를 바꿔도 결론이 같은지: 연봉·브랜드를 두 배로 키워 본다
W2 = {k: v * (2 if k in ("연봉", "브랜드") else 1) for k, v in W.items()}
t = sum(W2.values())
for name, s in offers.items():
    print(f"[연봉·브랜드 2배] {name}: {sum(W2[k] / t * s[k] for k in W2):.2f}")

